```'html'
<!DOCTYPE html>
<html lang='en'>

<head>
    <meta charset='UTF-8'>
    <meta name='viewport' content='width=device-width, initial-scale=1.0'>
    <title>Document</title>
    <style>
        /* 圆角 */
        .yuanjiao {
            width: 200px;
            height: 200px;
            background: pink;

            /* 圆角边框 */
            /* border-radius: 圆角半径; */
            border-radius: 10px;
            /* 四个角-一个值 */
            /* border-radius: 左上 右上 右下 左下; 四个值
            border-radius: 左上+右下 右上+左下; 两个值
            border-radius: 左上 右上+左下 右下; 三个值 */

        }

        /* 特殊做法 */
        /* 1.圆形的做法 */
        /* 高和宽相等，圆角半径等于一半 */
        .circle {
            width: 200px;
            height: 200px;
            background-color: pink;
            /* border-radius: 100px; 或者*/
            border-radius: 50%;
        }

        /* 2.圆角矩形的做法 */
        .circlesquare {
            width: 400px;
            height: 200px;
            background-color: pink;
            border-radius: 100px;
            /* 或者 border-radius: 50%; */
        }

        /* 3.可以设置不同的角 */
        /* 左上角 */
        .btl {
            width: 400px;
            height: 200px;
            background-color: pink;
            border-top-left-radius: 20px;
        }


        /* 盒子阴影 */
        .shadow {
            width: 200px;
            height: 200px;
            background-color: pink;
            /* 盒子阴影 */
            /* box-shadow: 影子在水平轴上距离（正右负左） 垂直 模糊程度 尺寸 颜色 内部阴影;
            水平与垂直距离是必须元素，其余不是
            当为内部阴影时加上inset，但外部不能写outset */
            box-shadow: 0 0 20px 15px rgba(0, 0, 0, .3);
        }

        /* 鼠标经过有阴影 */
        div:hover {
            box-shadow: 0 0 20px 15px rgba(0, 0, 0, .3);
        }


        /* 文字阴影 */
        .textshadow {
            font-size: 120px;
            font-weight: 800;
            /* text-shadow: 水平 垂直 模糊程度 颜色; */
            text-shadow: 0px 0px 25px red;
        }
    </style>
</head>

<body>
    <div class='yuanjiao'></div>
    1.圆形的做法
    <div class='circle'></div>
    2.圆角矩形的做法
    <div class='circlesquare'></div>
    3.设置单独角
    <div class='btl'></div>
    <br>
    盒子阴影
    <div class='shadow'></div>
    <br>
    文字阴影
    <p class='textshadow'>文字阴影</p>
</body>

</html>
